&lt;%
  // Group items by year
  const byYear = {};
  for (const item of items) {
    const yr = item.year;
    if (!byYear[yr]) byYear[yr] = [];
    byYear[yr].push(item);
  }
  // Get years in descending order
  const years = Object.keys(byYear).sort((a, b) =&gt; b - a);
%&gt;

&lt;% for (const year of years) { %&gt;

&lt;%= year %&gt;

  &lt;% for (const item of byYear[year]) { %&gt;

      [&lt;%= item.number %&gt;] &lt;%= item.authors %&gt;, &lt;%= item.title %&gt;. &lt;%= item.journal %&gt;&lt;% if (item.volume) { %&gt;, &lt;%= item.volume %&gt;&lt;% } %&gt;&lt;% if (item.pages) { %&gt;, &lt;%= item.pages %&gt;&lt;% } %&gt;&lt;% if (item.note) { %&gt; (&lt;%= item.note %&gt;)&lt;% } %&gt;.
      &lt;% if (item.doi) { %&gt;[DOI]&lt;% } %&gt;
      &lt;% if (item.pdf) { %&gt;[PDF]&lt;% } %&gt;

  &lt;% } %&gt;

&lt;% } %&gt;
